#!/usr/bin/env bash
#
# SlyTrade RL Bot — production upgrade, verify, commit & push.
#
# USAGE (from your VSCode terminal, inside the project folder):
#     bash apply_and_commit.sh            # upgrades the current directory
#     bash apply_and_commit.sh /path/to/slytrade-rl-bot
#
# What it does:
#   1. Safety-checks the repo (git repo, clean working tree, HEAD).
#   2. Extracts and applies the embedded patch (all 49 files).
#   3. Runs pytest / ruff / mypy (skips any that are not installed).
#   4. Commits on the current branch and pushes to origin.
#
set -euo pipefail

REPO_DIR="${1:-$(pwd)}"
cd "$REPO_DIR"
REPO_DIR="$(git rev-parse --show-toplevel 2>/dev/null || true)"
if [ -z "$REPO_DIR" ]; then
  echo "ERROR: not inside a git repository." >&2
  exit 1
fi
cd "$REPO_DIR"

# ---------------------------------------------------------------------------
# 1. Safety checks
# ---------------------------------------------------------------------------
if [ -n "$(git status --porcelain)" ]; then
  echo "ERROR: working tree is not clean. Commit or stash your local changes first:" >&2
  git status --short >&2
  exit 1
fi

if [ -z "$(git config user.email 2>/dev/null)" ] || [ -z "$(git config user.name 2>/dev/null)" ]; then
  echo "ERROR: git identity is not configured. Set it once, then re-run:" >&2
  echo "  git config --global user.email \"you@example.com\"" >&2
  echo "  git config --global user.name \"Your Name\"" >&2
  exit 1
fi

EXPECTED_HEAD="d9d4cb4"
ACTUAL_HEAD="$(git rev-parse --short HEAD)"
if [ "$ACTUAL_HEAD" != "$EXPECTED_HEAD" ]; then
  echo "WARNING: HEAD is $ACTUAL_HEAD but the patch was made against $EXPECTED_HEAD." >&2
  echo "         If 'git apply' fails, run:  git pull origin main   and retry." >&2
fi

# ---------------------------------------------------------------------------
# 2. Extract the embedded patch (base64 tail of this file)
# ---------------------------------------------------------------------------
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PATCH="$SCRIPT_DIR/.slytrade-upgrade.patch"
ARCHIVE_LINE="$(grep -n '^__PATCH_BELOW__$' "${BASH_SOURCE[0]}" | head -1 | cut -d: -f1)"
tail -n +$((ARCHIVE_LINE + 1)) "${BASH_SOURCE[0]}" | base64 -d > "$PATCH"
trap 'rm -f "$PATCH"' EXIT

# ---------------------------------------------------------------------------
# 3. Apply
# ---------------------------------------------------------------------------
echo ">> Applying upgrade patch..."
if ! git apply --check "$PATCH"; then
  echo "ERROR: patch does not apply cleanly to this tree." >&2
  echo "       Make sure you are on commit $EXPECTED_HEAD (git pull origin main)." >&2
  exit 1
fi
git apply "$PATCH"
echo ">> Patch applied (49 files)."

# ---------------------------------------------------------------------------
# 4. Verify
# ---------------------------------------------------------------------------
if python3 -c "import pytest" >/dev/null 2>&1; then
  echo ">> Running pytest..."
  python3 -m pytest -q
else
  echo "!! pytest not installed — skipping (pip install -e '.[dev,data]')"
fi

if command -v ruff >/dev/null 2>&1; then
  echo ">> Running ruff..."
  ruff check .
else
  echo "!! ruff not installed — skipping"
fi

if command -v mypy >/dev/null 2>&1; then
  echo ">> Running mypy..."
  mypy src
else
  echo "!! mypy not installed — skipping"
fi

# ---------------------------------------------------------------------------
# 5. Commit
# ---------------------------------------------------------------------------
COMMIT_MSG="$(mktemp)"
cat > "$COMMIT_MSG" <<'EOF'
feat: production runtime, observability, and deployment hardening

- Add paper-trading runtime loop (replay + live MT5 quote providers) with
  ICT feature streaming, managed SL/TP exits and SQLite journaling
- Add fail-closed runtime settings, structured JSON logging, Prometheus
  metrics server (/metrics /healthz /readyz)
- Add loss circuit breaker (consecutive losses, daily loss/trade caps,
  cooldown) and trading-window / red-folder news gate
- Add webhook + Telegram alerting (best-effort, never crashes the loop)
- Add risk-budgeted + fractional-Kelly position sizing and drawdown-aware
  RL reward shaping
- Add PPO/SAC/TD3 algorithm selection and optional MLflow tracking
- Add `slytrade paper|serve|reconcile` commands
- Containerize: multi-stage non-root Dockerfile, docker-compose, Kubernetes
  kustomize manifests (deployment/service/CronJob), hardened systemd unit
- CI: container build + coverage threshold; relax Python pin to >=3.12
- 210 tests passing, ruff + mypy clean
EOF

git add -A
git commit -F "$COMMIT_MSG"
rm -f "$COMMIT_MSG"

# ---------------------------------------------------------------------------
# 6. Push
# ---------------------------------------------------------------------------
if git remote get-url origin >/dev/null 2>&1; then
  BRANCH="$(git rev-parse --abbrev-ref HEAD)"
  echo ">> Pushing to origin/$BRANCH ..."
  git push -u origin "$BRANCH"
else
  echo "!! No 'origin' remote configured — commit created locally only."
fi

echo ""
echo "Done. Verify with:  git log --oneline -1"
echo "Next:               docker compose up -d paper"
exit 0
